    { view: AppView.DASHBOARD, icon: 'fa-grid-2', label: 'Hub' },
    { view: AppView.CHAT, icon: 'fa-brain-circuit', label: 'AI Help' },
    { view: AppView.LIVE_VOICE, icon: 'fa-waveform-lines', label: 'Voice' },
    { view: AppView.DIAGNOSTICS, icon: 'fa-list-check', label: 'Codes' },
  ];

  const isDashboard = activeView === AppView.DASHBOARD;

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-slate-950">
      {/* Darkened Header */}
      <header className="px-6 py-4 flex items-center justify-between bg-slate-950/80 backdrop-blur-md z-20 border-b border-slate-900">
        <div className="flex items-center gap-4">
          {!isDashboard ? (
            <button 
              onClick={onBack}
