            {isDashboard && <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-1">Smart Assistant</p>}
          </div>
        </div>
        <div className="flex items-center gap-2">
            <button className="w-11 h-11 rounded-full bg-slate-900 border border-slate-800 flex items-center justify-center text-slate-500">
