};

export default Layout;

import React, { useState, useEffect } from 'react';
import { AppView, ServiceRecord } from '../types';
import { getDailyMechanicalTip } from '../services/geminiService';

interface DashboardProps {
  onAction: (view: AppView) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ onAction }) => {
  const [tip, setTip] = useState<string>("Check valve clearances on high-mileage engines to prevent power loss and noisy operation.");
  const [isTipLoading, setIsTipLoading] = useState(false);

  const [history, setHistory] = useState<ServiceRecord[]>([]);
  const [newService, setNewService] = useState({ 
    type: '', 
    notes: '', 
    date: new Date().toISOString().split('T')[0],
    vehicle: '',
    regNo: '',
    engineRef: ''
  });
  const [showForm, setShowForm] = useState(false);

  useEffect(() => {
    const fetchTip = async () => {
      setIsTipLoading(true);
      try {
        const freshTip = await getDailyMechanicalTip();
        if (freshTip) setTip(freshTip.replace(/^"|"$/g, ''));
      } catch (e) {
        console.error("Tip fetch failed", e);
      } finally {
        setIsTipLoading(false);
      }
    };
    fetchTip();

    const savedHistory = localStorage.getItem('deemacai_service_history');
    if (savedHistory) setHistory(JSON.parse(savedHistory));
  }, []);

  const handleAddService = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newService.type || !newService.vehicle) return;

    const record: ServiceRecord = {
      id: Date.now().toString(),
      ...newService
    };

    const updatedHistory = [record, ...history];
    setHistory(updatedHistory);
    localStorage.setItem('deemacai_service_history', JSON.stringify(updatedHistory));

    setNewService({ 
      type: '', 
      notes: '', 
      date: new Date().toISOString().split('T')[0],
      vehicle: '',
      regNo: '',
      engineRef: ''
    });
    setShowForm(false);
  };

  const deleteRecord = (id: string) => {
    if(!confirm("Remove this entry?")) return;
    const updated = history.filter(h => h.id !== id);
    setHistory(updated);
    localStorage.setItem('deemacai_service_history', JSON.stringify(updated));
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-700 pb-36">

      {/* Dark Tip Bar */}
      <section className="px-6">
        <div className="bg-amber-500/10 border border-amber-500/20 rounded-2xl p-4 flex gap-4 items-center">
            <div className="flex-shrink-0 w-10 h-10 bg-slate-900 rounded-xl flex items-center justify-center text-amber-500 shadow-sm">
                <i className={`fa-solid ${isTipLoading ? 'fa-sync fa-spin' : 'fa-lightbulb'} text-sm`}></i>
            </div>
            <div className="flex-1">
                <span className="text-[9px] font-black text-amber-500/60 uppercase tracking-widest block mb-0.5">Shop Foreman Tip</span>
                <p className={`text-[13px] font-bold text-slate-200 leading-snug ${isTipLoading ? 'opacity-30' : ''}`}>
                    {tip}
                </p>
            </div>
        </div>
      </section>

      {/* Main Tool Grid - Dark Theme */}
      <section className="px-6 space-y-4">
        <div className="flex items-center justify-between">
            <h3 className="text-white font-black text-sm tracking-tight">Main Diagnostic Tools</h3>
            <span className="text-[10px] font-bold text-slate-600 uppercase tracking-widest">v3.2</span>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <button 
            onClick={() => onAction(AppView.AI_VISION)}
            className="col-span-2 group relative overflow-hidden flex items-center justify-between p-6 bg-slate-900 text-white rounded-[2rem] border border-slate-800 shadow-xl active:scale-[0.98] transition-all"
          >
            <div className="flex items-center gap-5 relative z-10">
              <div className="w-14 h-14 bg-amber-500 rounded-2xl flex items-center justify-center text-slate-950 text-2xl shadow-lg shadow-amber-500/20">
                <i className="fa-solid fa-camera-viewfinder"></i>
              </div>
              <div className="text-left">
                <p className="font-black text-xl leading-none">AI Part Scan</p>
                <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-2 opacity-80">Visual Recognition</p>
              </div>
            </div>
            <i className="fa-solid fa-arrow-right text-slate-600 group-hover:translate-x-1 transition-transform"></i>
            <div className="absolute top-0 right-0 w-32 h-32 bg-amber-500/5 -mr-8 -mt-8 rounded-full blur-2xl"></div>
          </button>

          <button 
            onClick={() => onAction(AppView.CHAT)}
            className="flex flex-col items-start p-5 bg-slate-900 border border-slate-800 rounded-[2rem] hover:border-indigo-500/30 active:scale-95 transition-all group"
          >
            <div className="w-11 h-11 bg-indigo-500/10 text-indigo-400 rounded-xl flex items-center justify-center mb-4 group-hover:bg-indigo-500 group-hover:text-white transition-all">
              <i className="fa-solid fa-brain-circuit text-lg"></i>
            </div>
            <span className="font-black text-white text-sm">Tech Advisor</span>
            <span className="text-[9px] text-slate-500 font-black uppercase mt-1 tracking-wider">Troubleshooting</span>
          </button>

          <button 
            onClick={() => onAction(AppView.DIAGNOSTICS)}
            className="flex flex-col items-start p-5 bg-slate-900 border border-slate-800 rounded-[2rem] hover:border-rose-500/30 active:scale-95 transition-all group"
          >
            <div className="w-11 h-11 bg-rose-500/10 text-rose-400 rounded-xl flex items-center justify-center mb-4 group-hover:bg-rose-500 group-hover:text-white transition-all">
              <i className="fa-solid fa-barcode text-lg"></i>
            </div>
            <span className="font-black text-white text-sm">DTC Library</span>
            <span className="text-[9px] text-slate-500 font-black uppercase mt-1 tracking-wider">Error Codes</span>
          </button>

          <button 
            onClick={() => onAction(AppView.QUICK_SPECS)}
            className="flex flex-col items-start p-5 bg-slate-900 border border-slate-800 rounded-[2rem] hover:border-sky-500/30 active:scale-95 transition-all group"
          >
            <div className="w-11 h-11 bg-sky-500/10 text-sky-400 rounded-xl flex items-center justify-center mb-4 group-hover:bg-sky-500 group-hover:text-white transition-all">
              <i className="fa-solid fa-list-check text-lg"></i>
            </div>
            <span className="font-black text-white text-sm">Factory Specs</span>
            <span className="text-[9px] text-slate-500 font-black uppercase mt-1 tracking-wider">Fluid & Torque</span>
          </button>

          <button 
            onClick={() => onAction(AppView.MANUALS)}
            className="flex flex-col items-start p-5 bg-slate-900 border border-slate-800 rounded-[2rem] hover:border-slate-500 active:scale-95 transition-all group"
          >
            <div className="w-11 h-11 bg-slate-800 text-slate-400 rounded-xl flex items-center justify-center mb-4 group-hover:bg-white group-hover:text-slate-950 transition-all">
              <i className="fa-solid fa-book-open text-lg"></i>
            </div>
            <span className="font-black text-white text-sm">Archive</span>
            <span className="text-[9px] text-slate-500 font-black uppercase mt-1 tracking-wider">Service Manuals</span>
          </button>
        </div>
      </section>

      {/* Service Journal Section - Dark Theme */}
      <section className="px-6 space-y-4 animate-in slide-in-from-bottom-4 duration-500">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <h3 className="text-white font-black text-sm tracking-tight">Active Jobs Journal</h3>
            <span className="bg-slate-900 text-slate-500 text-[10px] px-2 py-0.5 rounded-full font-bold border border-slate-800">{history.length}</span>
          </div>
          <button 
            onClick={() => setShowForm(!showForm)}
            className="text-amber-500 bg-amber-500/10 px-4 py-2 rounded-xl text-[10px] font-black uppercase active:scale-95 transition-all border border-amber-500/20"
          >
            {showForm ? 'Close' : '+ New Record'}
          </button>
        </div>

        {showForm && (
          <form onSubmit={handleAddService} className="bg-slate-900 p-6 rounded-[2.5rem] border border-slate-800 shadow-2xl space-y-5 animate-in zoom-in-95 duration-300">
            <div className="space-y-4">
              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-600 uppercase tracking-widest ml-1">Vehicle Description</label>
                <input 
                  type="text"
                  placeholder="e.g. 2021 BMW M3"
                  value={newService.vehicle}
                  onChange={(e) => setNewService({...newService, vehicle: e.target.value})}
                  className="w-full bg-slate-950 border border-slate-800 rounded-2xl px-5 py-4 text-white text-sm focus:border-amber-500 transition-all outline-none placeholder:text-slate-700"
                  required
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <input 
                  type="text"
                  placeholder="Reg No."
                  value={newService.regNo}
                  onChange={(e) => setNewService({...newService, regNo: e.target.value.toUpperCase()})}
                  className="w-full bg-slate-950 border border-slate-800 rounded-2xl px-5 py-4 text-white text-sm focus:border-amber-500 transition-all outline-none placeholder:text-slate-700"
                />
                <input 
                  type="text"
                  placeholder="VIN/Engine"
                  value={newService.engineRef}
                  onChange={(e) => setNewService({...newService, engineRef: e.target.value.toUpperCase()})}
                  className="w-full bg-slate-950 border border-slate-800 rounded-2xl px-5 py-4 text-white text-sm focus:border-amber-500 transition-all outline-none placeholder:text-slate-700"
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <input 
                  type="date"
                  value={newService.date}
                  onChange={(e) => setNewService({...newService, date: e.target.value})}
                  className="w-full bg-slate-950 border border-slate-800 rounded-2xl px-5 py-4 text-white text-sm outline-none"
                />
                <input 
                  type="text"
                  placeholder="Job Title"
                  value={newService.type}
                  onChange={(e) => setNewService({...newService, type: e.target.value})}
                  className="w-full bg-slate-950 border border-slate-800 rounded-2xl px-5 py-4 text-white text-sm focus:border-amber-500 transition-all outline-none placeholder:text-slate-700"
                  required
