export default Dashboard;

import React, { useState, useRef, useEffect } from 'react';
import { Message } from '../types';
import { getGeminiResponse } from '../services/geminiService';

const ChatInterface: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: '1',
      role: 'assistant',
      content: 'Hello! I am your AI Mechanic Assistant. What can I help you troubleshoot today?',
      timestamp: Date.now()
    }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() && !selectedImage) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: Date.now(),
      image: selectedImage || undefined
    };

    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const response = await getGeminiResponse(input || "What do you see in this image?", userMessage.image);
      const aiMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response || "I'm sorry, I couldn't process that.",
        timestamp: Date.now()
      };
      setMessages(prev => [...prev, aiMessage]);
    } catch (error) {
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'assistant',
        content: "Error connecting to service.",
        timestamp: Date.now()
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setSelectedImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-950">
      <div className="flex-1 overflow-y-auto p-6 space-y-6">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] rounded-[2rem] p-5 shadow-sm ${
              msg.role === 'user' 
              ? 'bg-amber-500 text-slate-950 rounded-br-none font-bold' 
              : 'bg-slate-900 text-slate-200 border border-slate-800 rounded-bl-none'
            }`}>
              {msg.image && (
                <img src={msg.image} alt="Uploaded part" className="rounded-2xl mb-3 max-h-60 w-full object-cover border border-slate-700" />
              )}
              <div className="text-sm leading-relaxed whitespace-pre-wrap">{msg.content}</div>
              <div className={`text-[10px] opacity-40 mt-2 text-right ${msg.role === 'user' ? 'text-slate-900' : 'text-slate-500'}`}>
                {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-slate-900 rounded-[2rem] px-5 py-4 border border-slate-800 rounded-bl-none">
              <div className="flex gap-1.5">
                <div className="w-1.5 h-1.5 bg-amber-500 rounded-full animate-bounce"></div>
                <div className="w-1.5 h-1.5 bg-amber-500 rounded-full animate-bounce delay-100"></div>
                <div className="w-1.5 h-1.5 bg-amber-500 rounded-full animate-bounce delay-200"></div>
              </div>
            </div>
          </div>
        )}
        <div ref={chatEndRef} />
      </div>

      <div className="p-6 bg-slate-950 border-t border-slate-900">
        <div className="flex items-end gap-3">
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="p-4 rounded-2xl bg-slate-900 text-slate-500 hover:text-amber-500 transition-colors border border-slate-800"
          >
            <i className="fa-solid fa-camera text-xl"></i>
          </button>
          <input type="file" ref={fileInputRef} onChange={handleImageUpload} accept="image/*" className="hidden" />

          <div className="flex-1 bg-slate-900 rounded-[1.5rem] px-4 py-1 flex items-center border border-slate-800">
             <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Type a symptom or code..."
              className="flex-1 bg-transparent text-white text-sm py-3 focus:outline-none resize-none max-h-32 placeholder:text-slate-700"
              rows={1}
            />
          </div>

          <button 
            onClick={handleSend}
            disabled={(!input.trim() && !selectedImage) || isLoading}
            className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${
              (input.trim() || selectedImage) && !isLoading
              ? 'bg-amber-500 text-slate-950 shadow-lg shadow-amber-500/20' 
              : 'bg-slate-900 text-slate-700'
            }`}
          >
            <i className="fa-solid fa-paper-plane"></i>
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatInterface;

import React, { useState } from 'react';
import { getGeminiResponse } from '../services/geminiService';

const Diagnostics: React.FC = () => {
  const [code, setCode] = useState('');
  const [result, setResult] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const handleLookup = async () => {
    if (!code) return;
    setLoading(true);
    try {
      const prompt = `Provide a detailed diagnostic breakdown for the OBD-II code: ${code}. Include meaning, common symptoms, possible causes (ordered by probability), and suggested repair steps. Keep it professional and technical.`;
      const response = await getGeminiResponse(prompt);
      setResult(response);
    } catch (e) {
      setResult("Could not fetch information for this code.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-6 space-y-8 animate-in fade-in duration-500 bg-slate-950 min-h-full">
      <header>
        <div className="w-14 h-14 bg-rose-500/10 text-rose-500 rounded-2xl flex items-center justify-center mb-4 border border-rose-500/20">
            <i className="fa-solid fa-barcode text-2xl"></i>
        </div>
        <h2 className="text-2xl font-black text-white tracking-tight leading-none mb-2">Code Scanner Aid</h2>
        <p className="text-slate-500 text-sm leading-relaxed">Enter a DTC to get a professional breakdown and troubleshooting steps.</p>
      </header>

      <div className="bg-slate-900 p-2 rounded-[2rem] border border-slate-800 shadow-2xl">
        <div className="flex items-center p-1">
          <input 
            type="text" 
            placeholder="P0420"
            value={code}
            onChange={(e) => setCode(e.target.value.toUpperCase())}
            className="flex-1 bg-transparent rounded-2xl px-5 py-4 text-white font-black text-xl placeholder:text-slate-800 outline-none uppercase"
          />
          <button 
            onClick={handleLookup}
            disabled={loading || !code}
