  return (
    <div className="flex flex-col h-screen overflow-hidden bg-slate-950">
      {/* Premium Header */}
      <header className="px-6 py-4 flex items-center justify-between bg-slate-950/90 backdrop-blur-xl z-20 border-b border-slate-900 flex-shrink-0">
        <div className="flex items-center gap-4">
          {!isDashboard ? (
            <button 
              onClick={onBack}
              className="bg-slate-900 text-white p-2.5 rounded-2xl w-11 h-11 flex items-center justify-center active:scale-90 active:bg-slate-800 transition-all border border-slate-800 shadow-lg shadow-black/50"
              aria-label="Go back"
            >
              <i className="fa-solid fa-chevron-left text-amber-500"></i>
            </button>
          ) : (
            <div className="w-11 h-11 bg-amber-500/10 rounded-2xl flex items-center justify-center text-amber-500 border border-amber-500/20">
              <i className="fa-solid fa-screwdriver-wrench text-lg"></i>
