import { GoogleGenAI, Modality, Type } from "@google/genai";

// Always use process.env.API_KEY directly in the client initialization.
export const getGeminiResponse = async (prompt: string, imageBase64?: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = "gemini-3-pro-preview";

  const contents: any[] = [{ text: prompt }];

  if (imageBase64) {
    contents.push({
      inlineData: {
        mimeType: "image/jpeg",
        data: imageBase64.split(',')[1] || imageBase64
      }
    });
  }

  const response = await ai.models.generateContent({
    model,
    contents: { parts: contents.map(p => typeof p === 'string' ? {text: p} : p) },
    config: {
      systemInstruction: "You are a world-class master mechanic with 40 years of experience. You provide precise, technical, and safe automotive advice. Use technical terms correctly but explain them if they are complex. Focus on troubleshooting steps, torque specs, and safety warnings.",
    }
  });

  return response.text;
};

